@module fs  src=fs.lua  loc=121  mode=namespace  self=fs

# Shapes
  @shape  fileOps = { copy(src,dst)->bool, move(src,dst)->bool, mkdir(dir), exists(path)->bool, hash(path)->string }  @ 107

# Module-level constants
  @const fs = {}  @ 5
      @invariant  sole module touching reaper.Enumerate* and filesystem IO; UI/view layers route through here  @ 3
      @invariant  listDirs and listAudioFiles return case-insensitively sorted output (Finder/Explorer parity)  @ 4
  @const AUDIO_EXTS = {  @ 7

# Private functions
  @fn ciLess(a, b)  @ 34
  @fn copyFile(src, dst)  @ 95-105
      -- 64KB chunks so big samples don't allocate a Lua string the size of the file.

# Functions held in tables
  @held fileOps.move(src, dst)  @ 111-115
  @held fileOps.mkdir(dir)  @ 116

# Public API (fs.*)
  @api fs.isAudio(name)  @ 12-16
  @api fs.basename(path)  @ 18-20
  @api fs.parent(path)  @ 23-25
      @contract  returns '' if path has no separator; trailing separators on input are not stripped (caller passes canonical paths)  @ 22
  @api fs.join(a, b)  @ 28-32
      @contract  inserts '/' between a and b unless a already ends in '/' or '\\'; no path normalisation  @ 27
  @api fs.listDirs(path)  @ 37-47
      @contract  hides dotfile-prefixed entries (.git, .DS_Store, etc.)  @ 36
  @api fs.exists(path)  @ 49-53
  @api fs.readText(path)  @ 55-58
  @api fs.hashFile(path)  @ 61-80
      @contract  FNV-1a over (size, first 4KB, last 4KB); 8-char hex; non-cryptographic; see docs/fs.md  @ 60
  @api fs.listAudioFiles(path)  @ 82-92

# Calls (intra-file)
  @call copyFile  @ fileOps.move:113
  @call fs.isAudio  @ listAudioFiles:87

# Bindings (by name)
  @bind ciLess  @ listDirs:45 listAudioFiles:90
  @bind copyFile  @ 109

# Unresolved receivers
  @drop a:lower  @ ciLess:34
  @drop a:sub  @ join:29
  @drop b:lower  @ ciLess:34
  @drop data:byte  @ hashFile:77
  @drop ext:lower  @ isAudio:15
  @drop f:close  @ exists:51 readText:57 hashFile:73
  @drop f:read  @ readText:57 hashFile:67,71
  @drop f:seek  @ hashFile:64,65,66,70
  @drop fin:close  @ copyFile:97,103
  @drop fin:read  @ copyFile:99
  @drop fout:close  @ copyFile:103
  @drop fout:write  @ copyFile:101
  @drop name:match  @ isAudio:13
  @drop path:match  @ basename:19 parent:24
  @drop sub:sub  @ listDirs:42

# REAPER API surface
  @reaper EnumerateSubdirectories
  @reaper EnumerateFiles
  @reaper RecursiveCreateDirectory

# Fields (r read / w write incl. constructor keys)
  @field w aif  @ 8
  @field w aiff  @ 8
  @field w basename  @ basename:18
  @field w copy  @ 109
  @field r exists  @ 117
  @field w exists  @ exists:49 117
  @field w fileOps  @ 108
  @field w flac  @ 8
  @field w hash  @ 118
  @field r hashFile  @ 118
  @field w hashFile  @ hashFile:61
  @field w isAudio  @ isAudio:12
  @field w join  @ join:28
  @field w listAudioFiles  @ listAudioFiles:82
  @field w listDirs  @ listDirs:37
  @field w m4a  @ 9
  @field w mkdir  @ fileOps.mkdir:116
  @field w move  @ fileOps.move:111
  @field w mp3  @ 9
  @field w ogg  @ 9
  @field w opus  @ 9
  @field w parent  @ parent:23
  @field w readText  @ readText:55
  @field w wav  @ 8
